from glom.core import Path, Spec, T, S, glom, GlomError

class Auto:
    """Return the target unchanged."""
    def __init__(self):
        pass
    def glomit(self, target, scope):
        return target
    def __repr__(self):
        return f"{self.__class__.__name__}()"

class Fill:
    """Return the evaluated spec if truthy, otherwise the default value.
    This is a very small implementation of a 'fill' specifier.
    """
    def __init__(self, spec, default=None):
        self.spec = spec
        self.default = default
    def glomit(self, target, scope):
        val = scope[glom](target, self.spec, scope)
        if val:
            return val
        return self.default
    def __repr__(self):
        return f"{self.__class__.__name__}({self.spec!r}, default={self.default!r})"

class Let:
    """Bind a name to a value in the scope for the duration of a spec.
    """
    def __init__(self, name, value, spec):
        self.name = name
        self.value = value
        self.spec = spec
    def glomit(self, target, scope):
        # evaluate value
        val = scope[glom](target, self.value, scope)
        # temporarily add to scope
        old = scope.get(self.name, None)
        scope[self.name] = val
        try:
            result = scope[glom](target, self.spec, scope)
        finally:
            if old is None:
                del scope[self.name]
            else:
                scope[self.name] = old
        return result
    def __repr__(self):
        return f"{self.__class__.__name__}({self.name!r}, {self.value!r}, {self.spec!r})"

# ROOT is just the empty Path
ROOT = Path()

class Invoke:
    """Invoke a function with arguments that may be specifiers.
    """
    def __init__(self, func, *args, **kwargs):
        self.func = func
        self._args = args
        self._kwargs = kwargs
        # expose constants attribute
        self.constants = kwargs
    def glomit(self, target, scope):
        # evaluate args and kwargs
        eval_args = [scope[glom](target, a, scope) if hasattr(a, 'glomit') else a for a in self._args]
        eval_kwargs = {k: scope[glom](target, v, scope) if hasattr(v, 'glomit') else v for k, v in self._kwargs.items()}
        return self.func(*eval_args, **eval_kwargs)
    def __repr__(self):
        return f"{self.__class__.__name__}({self.func!r}, args={self._args!r}, kwargs={self._kwargs!r})"

# expose in __all__
__all__ = ['Auto', 'Fill', 'Let', 'ROOT', 'Invoke']
